 indirectCash:COST_DEFS.filter(x=>x[0]==='indirect').map(x=>[x[1],r.payments[x[2]]]).concat([['Выплаты косвенных расходов',r.indirectPayments,true]]),
 cash:[['Поступления',r.inflow],['Выплаты по расходам',r.operatingPayments.map(x=>-x)],['Налоговые выплаты',r.vatPay.map(x=>-x)],['Чистый денежный поток',r.ncf,true],['Поток накопительно',r.cumulative,true,'last']],
