function makeModelTable(r){const v=version(),neg=a=>a.map(x=>-x),income=[['Выполнение по КСГ × KQ / ручной ряд',r.revenue.map((x,m)=>x-v.drivers.otherRevenue[m])],['Прочие доходы',v.drivers.otherRevenue]],receipts=[['Оплата за работы',v.drivers.payments],['Полученные авансы',v.drivers.advances],...(v.cashFlowBasis==='source_model'?[]:[['Зачёт авансов',v.drivers.advanceOffset.map(x=>-x)]]),['Факторинг',v.drivers.factoring]],taxes=[['НДС с поступлений',r.outputVat],['НДС с авансов',r.advanceVat],['НДС с зачёта авансов',r.offsetVat],['НДС входящий',neg(r.inputVat)],['Модельная выплата НДС',neg(r.vatPay)]];let rows=`<tr class="table-section"><td colspan="14">Технико-экономические показатели</td></tr>`;rows+=treeRow({label:'Физический объём (КСГ / KQ-2)',row:v.drivers.physicalVolume,raw:true});rows+=treeRow({label:'Основной персонал, чел.',row:v.drivers.directPeople,raw:true});rows+=treeRow({label:'Вспомогательный персонал, чел.',row:v.drivers.indirectPeople,raw:true});rows+=treeRow({label:'Техника, маш.-ч',row:v.drivers.equipmentHours,raw:true});rows+=`<tr class="table-section"><td colspan="14">Экономические показатели</td></tr>`;rows+=treeRow({key:'model-income',label:'Доходы',row:r.revenue,toggle:true});rows+=income.map(x=>treeRow({parent:'model-income',label:x[0],row:x[1],level:1})).join('');rows+=treeRow({key:'model-costs',label:'Расходы',row:r.costs,toggle:true});rows+=treeRow({key:'model-direct',parent:'model-costs',label:'Прямые',row:r.direct,level:1,toggle:true});rows+=COST_DEFS.filter(x=>x[0]==='direct').map(x=>treeRow({parent:'model-direct',label:x[1],row:r.rows[x[2]],level:2})).join('');rows+=treeRow({key:'model-indirect',parent:'model-costs',label:'Косвенные',row:r.indirect,level:1,toggle:true});rows+=COST_DEFS.filter(x=>x[0]==='indirect').map(x=>treeRow({parent:'model-indirect',label:x[1],row:r.rows[x[2]],level:2})).join('');rows+=treeRow({label:'Финансовый результат',row:r.profit,total:true});rows+=`<tr class="table-section"><td colspan="14">Финансовые показатели</td></tr>`;if(Array.isArray(v.drivers.ks2Accepted))rows+=treeRow({label:'Принято по КС-2 (с учётом документации)',row:v.drivers.ks2Accepted});if(Array.isArray(v.drivers.primaryExecuted))rows+=treeRow({label:'Факт выполнения по первичке (подрядчик и проект)',row:v.drivers.primaryExecuted});if(v.cashFlowBasis==='source_model')rows+=treeRow({label:'Расчётная задолженность по первичке',row:r.receivable});rows+=treeRow({key:'model-receipts',label:'Поступления',row:r.inflow,toggle:true});rows+=receipts.map(x=>treeRow({parent:'model-receipts',label:x[0],row:x[1],level:1})).join('');rows+=treeRow({key:'model-payments',label:'Выплаты подрядчика по статьям расходов',row:neg(r.operatingPayments),toggle:true});rows+=treeRow({key:'model-direct-payments',parent:'model-payments',label:'Прямые',row:neg(r.directPayments),level:1,toggle:true});rows+=COST_DEFS.filter(x=>x[0]==='direct').map(x=>treeRow({parent:'model-direct-payments',label:x[1],row:neg(r.payments[x[2]]),level:2})).join('');rows+=treeRow({key:'model-indirect-payments',parent:'model-payments',label:'Косвенные',row:neg(r.indirectPayments),level:1,toggle:true});rows+=COST_DEFS.filter(x=>x[0]==='indirect').map(x=>treeRow({parent:'model-indirect-payments',label:x[1],row:neg(r.payments[x[2]]),level:2})).join('');rows+=treeRow({key:'model-taxes',label:'Налоговые выплаты',row:neg(r.vatPay),toggle:true});rows+=taxes.map(x=>treeRow({parent:'model-taxes',label:x[0],row:x[1],level:1})).join('');rows+=treeRow({label:'Чистый денежный поток',row:r.ncf,total:true});rows+=treeRow({label:'Поток накопительно',row:r.cumulative,total:true,last:true});const statuses=MONTHS.map((_,m)=>`<th class="period-kind">${m<v.actualThroughMonth?(v.primaryIdentityConfirmed?'Факт':'Факт не подтверждён'):'Прогноз'}</th>`).join('');return `<table class="model-table"><thead><tr><th>Показатель<br><small>денежные суммы: ${esc(unitName())}</small></th>${MONTHS.map(x=>`<th>${x}</th>`).join('')}<th>За год / на конец</th></tr><tr><th>Тип периода</th>${statuses}<th>Факт + прогноз</th></tr></thead><tbody>${rows}</tbody></table>`;}
function makeDetailedModelTable(r){const v=version(),allWorks=rankedWorks(v),works=topWorkRows(v),otherAmounts=Array.from({length:12},(_,m)=>r.revenue[m]-(v.drivers.otherRevenue[m]||0)-sum(allWorks.slice(0,10).map(x=>x.amounts[m])));let tech=`<tr class="table-section"><td colspan="14">Технико-экономические показатели</td></tr>`;tech+=treeRow({key:'model-top-works',label:'КФО · топ-10 видов работ',row:Array(12).fill(0),toggle:true,raw:true});tech+=works.map(x=>treeRow({parent:'model-top-works',label:x.label,row:x.volumes,level:1,raw:true})).join('');tech+=treeRow({label:'Основной персонал, FTE',row:v.drivers.directPeople,raw:true});tech+=treeRow({label:'Вспомогательный персонал, FTE',row:v.drivers.auxiliaryPeople,raw:true});tech+=treeRow({label:'Косвенный персонал, FTE',row:v.drivers.indirectPeople,raw:true});tech+=treeRow({label:'Техника, FTE',row:fteRow(v.drivers.equipmentHours),raw:true});const economy=`<tr class="table-section"><td colspan="14">Экономические показатели</td></tr>`;let html=makeModelTable(r).replace(/<tr class="table-section"><td colspan="14">Технико-экономические показатели<\/td><\/tr>[\s\S]*?<tr class="table-section"><td colspan="14">Экономические показатели<\/td><\/tr>/,tech+economy);if(allWorks.length){const details=allWorks.slice(0,10).map(x=>treeRow({parent:'model-income',label:x.label,row:x.amounts,level:1})).join('')+treeRow({parent:'model-income',label:'Прочие работы / остаток',row:otherAmounts,level:1})+treeRow({parent:'model-income',label:'Прочие доходы',row:v.drivers.otherRevenue,level:1});html=html.replace(/(<tr[^>]*data-tree-key="model-income"[\s\S]*?<\/tr>)[\s\S]*?(<tr[^>]*data-tree-key="model-costs")/,'$1'+details+'$2');}return html;}
function bindTreeTable(container){const toggles=[...container.querySelectorAll('[data-tree-key]')],byKey=Object.fromEntries(toggles.map(x=>[x.dataset.treeKey,x]));const update=()=>container.querySelectorAll('[data-tree-parent]').forEach(row=>{let key=row.dataset.treeParent,visible=true;while(key){const parent=byKey[key];if(!parent?.classList.contains('expanded')){visible=false;break;}key=parent.dataset.treeParent||'';}row.classList.toggle('hidden',!visible);});const toggle=el=>{const open=!el.classList.contains('expanded');el.classList.toggle('expanded',open);el.title=open?'Свернуть детализацию':'Развернуть детализацию';update();};toggles.forEach(el=>{el.onclick=()=>toggle(el);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle(el);}};});update();}
