function renderCostFactorAnalysis(other,current,a,b,canRub,factorCurrency){if(!factorCurrency)return'<h4>Расходы: факторный мост</h4><p class="sub">Для версий в разных валютах укажите оба курса к RUB.</p>';const result=CalculationCore.compareWorkItems(costFactorItems(other,a),costFactorItems(current,b),{baseFx:canRub?fxOf(other):1,currentFx:canRub?fxOf(current):1}),base=canRub?rub(sum(a.costs),other):sum(a.costs),actual=canRub?rub(sum(b.costs),current):sum(b.costs),residual=CalculationCore.residualFactor({base,current:actual,explained:result.total.variance}),control=actual-base-result.total.variance-residual,moneyUnit=unitName(factorCurrency),statusLabel={matched:'Сопоставлена',new:'Новая',removed:'Исключена'},rows=result.rows.map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.label)}</td><td>${esc(x.unit)}</td><td>${fmtQuantity(x.q0)}</td><td>${x.rawP0==null?'—':fmtRaw(x.p0)}</td><td>${fmtQuantity(x.q1)}</td><td>${x.rawP1==null?'—':fmtRaw(x.p1)}</td><td>${fmtRaw(x.base)}</td><td>${fmtRaw(x.volume)}</td><td>${fmtRaw(x.price)}</td><td>${fmtRaw(x.variance)}</td><td>${fmtRaw(x.current)}</td><td>${fmtRaw(x.control)}</td><td>${statusLabel[x.status]||esc(x.status)}</td></tr>`).join('');return`<h4>Расходы: факторный мост по драйверам</h4><div class="tablewrap"><table class="small-table"><thead><tr><th>Группа</th><th>Статья</th><th>Драйвер</th><th>База: количество</th><th>База: ставка, ${moneyUnit}</th><th>Текущее количество</th><th>Текущая ставка, ${moneyUnit}</th><th>Сумма базы, ${moneyUnit}</th><th>Фактор объёма</th><th>Фактор цены</th><th>Отклонение</th><th>Сумма текущая, ${moneyUnit}</th><th>Контроль</th><th>Статус</th></tr></thead><tbody>${rows}<tr><td colspan="10">Остаточный фактор: налоги, процентные базы, ручные суммы и статьи без отдельной ставки</td><td>${fmtRaw(residual)}</td><td></td><td></td><td>Остаток</td></tr><tr class="total"><td colspan="7">Итого расходов</td><td>${fmtRaw(base)}</td><td>${fmtRaw(result.total.volume)}</td><td>${fmtRaw(result.total.price)}</td><td>${fmtRaw(actual-base)}</td><td>${fmtRaw(actual)}</td><td>${fmtRaw(control)}</td><td></td></tr></tbody></table></div><p class="sub">Положительный фактор означает рост расходов. Остаточный фактор замыкает общее отклонение и не подменяет отсутствующие количество или ставку.</p>`;}
function renderComparison(){
 const select=$('compareVersion'),previous=select.value;
 select.innerHTML=contract().versions.filter(x=>x.id!==state.currentVersion).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');
 if([...select.options].some(x=>x.value===previous))select.value=previous;
 const other=contract().versions.find(x=>x.id===select.value);
 if(!other){$('factorTable').innerHTML='<p class="sub">Сохраните вторую версию для сравнения.</p>';return;}
 const current=version(),a=calcModel(other),b=state.results;
 const metrics=[['Доходы',sum(a.revenue),sum(b.revenue)],['Расходы',sum(a.costs),sum(b.costs)],['Результат',sum(a.profit),sum(b.profit)],['Поток на конец',a.cumulative.at(-1),b.cumulative.at(-1)]];
 const sameCurrency=other.currency===current.currency,canRub=fxOf(other)>0&&fxOf(current)>0;
 const factorCurrency=canRub?'RUB':sameCurrency?current.currency:null;
 const convert=(n,v)=>canRub?rub(n,v):n;
 const analysis=factorCurrency?CalculationCore.compareWorkItems(other.workItems,current.workItems,{baseFx:canRub?fxOf(other):1,currentFx:canRub?fxOf(current):1}):{rows:[],total:{base:0,current:0,volume:0,price:0,variance:0,control:0}};
 const ranked=CalculationCore.topWorkFactors(analysis.rows,10);
 const statusLabel={matched:'Сопоставлена',new:'Новая',removed:'Исключена',unmatched:'Нет данных'};
 const detail=x=>`<details class="factor-row-details"><summary>${esc(x.label)}</summary><div>База: ${fmtQuantity(x.q0)} ${esc(x.unit||'')}, ставка ${x.rawP0==null?'—':fmtRaw(x.p0)}; текущая: ${fmtQuantity(x.q1)} ${esc(x.unit||'')}, ставка ${x.rawP1==null?'—':fmtRaw(x.p1)}. ${statusLabel[x.status]||esc(x.status)}</div></details>`;
 const row=x=>`<tr><td>${esc(x.code||'—')}</td><td>${detail(x)}</td><td>${fmtRaw(x.base)}</td><td>${fmtRaw(x.volume)}</td><td>${fmtRaw(x.price)}</td><td>${fmtRaw(x.current)}</td><td>${fmtRaw(x.control)}</td></tr>`;
 const otherRow=ranked.other?`<tr class="factor-other"><td>—</td><td>${esc(ranked.other.label)}</td><td>${fmtRaw(ranked.other.base)}</td><td>${fmtRaw(ranked.other.volume)}</td><td>${fmtRaw(ranked.other.price)}</td><td>${fmtRaw(ranked.other.current)}</td><td>${fmtRaw(ranked.other.control)}</td></tr>`:'';
 const summary=`<table class="factor-summary"><thead><tr><th>Показатель</th><th>${esc(other.name)}, ${esc(factorCurrency||other.currency)}</th><th>${esc(current.name)}, ${esc(factorCurrency||current.currency)}</th><th>Изменение, ${esc(factorCurrency||'нет курса')}</th></tr></thead><tbody>${metrics.map(x=>{const left=convert(x[1],other),right=convert(x[2],current);return`<tr><td>${x[0]}</td><td>${fmtRaw(left)}</td><td>${fmtRaw(right)}</td><td>${fmtRaw(factorCurrency?right-left:NaN)}</td></tr>`;}).join('')}</tbody></table>`;
 const bridge=ranked.visible.length?`<div class="tablewrap factor-tablewrap"><table class="factor-table"><thead><tr><th>KQ-2</th><th>Работа · количество и ставка</th><th>База</th><th>Объём</th><th>Цена</th><th>Текущая</th><th>Контроль</th></tr></thead><tbody>${ranked.visible.map(row).join('')}${otherRow}<tr class="total"><td></td><td>Все работы</td><td>${fmtRaw(analysis.total.base)}</td><td>${fmtRaw(analysis.total.volume)}</td><td>${fmtRaw(analysis.total.price)}</td><td>${fmtRaw(analysis.total.current)}</td><td>${fmtRaw(analysis.total.control)}</td></tr></tbody></table></div>`:factorCurrency?'<p class="sub">В версиях пока нет канонических работ с объёмами и ставками.</p>':'<p class="sub">Для версий в разных валютах укажите оба курса к RUB.</p>';
 $('factorTable').innerHTML=`<div class="factor-compact"><div class="tablewrap">${summary}</div><div class="factor-heading"><h4>Доходы: десять ключевых работ</h4><span class="sub">По большей стоимости в двух версиях · ${esc(unitName(factorCurrency||current.currency))}</span></div>${bridge}<details class="factor-method"><summary>Метод и допущения</summary><p>Последовательная подстановка: сначала объём, затем цена. Остальные ${ranked.hiddenCount} работ объединены без потери факторов. ${canRub?'Расчёт в RUB, курсовая разница входит в цену.':sameCurrency?'Расчёт в валюте договора.':'Для разных валют нужны оба курса.'}</p></details><details class="factor-expenses"><summary>Расходы: факторный мост и детализация</summary>${renderCostFactorAnalysis(other,current,a,b,canRub,factorCurrency)}</details></div>`;
}
function changeParameter(e){if(!editMode||!version())return;const el=e.target,v=version();try{
 if(el.hasAttribute('data-material-markup')){const value=Number(el.value);if(el.value===''||!Number.isFinite(value)||value<0||value>1000)throw Error('Укажите наценку материалов от 0 до 1000%.');v.costSourceBasis=v.costSourceBasis||{};v.costSourceBasis.materialMarkupPercent=value;}
 else if(el.dataset.basis){v.costSourceBasis=v.costSourceBasis||{};v.costSourceBasis[el.dataset.basis]=el.checked;}
 else if(el.dataset.general){const k=el.dataset.general,value=el.value.trim();if(['year','vatRate','actualThroughMonth'].includes(k)){if(!el.checkValidity()||value==='')throw Error('Проверьте числовое значение.');v[k]=Number(value);if(k==='year')v.portfolioYearMissing=false;}else if(k==='contractorName'){if(!value)throw Error('Укажите имя подрядчика.');contractor().name=value;}else if(k==='versionName'){if(!value)throw Error('Укажите название версии.');v.name=value;}else if(k==='vacationBasis')v[k]=value;else{if(!value)throw Error('Поле не может быть пустым.');contract()[k]=value;}}
 else if(el.dataset.driver){const n=Number(el.value);if(el.value===''||!Number.isFinite(n))throw Error('Введите число.');const s=SERIES.find(x=>x[0]===el.dataset.driver);v.drivers[s[0]][Number(el.dataset.month)]=n*(s[2]?state.unit:1);v.dataMode='manual';}
 else if(el.dataset.manual){const [kind,k]=el.dataset.manual.split(':');if(el.value===''||!Number.isFinite(Number(el.value)))throw Error('Введите число.');v[kind==='cost'?'manualCosts':'manualPayments'][k][Number(el.dataset.month)]=Number(el.value)*state.unit;v.dataMode='manual';}
 else if(el.dataset.cost){const p=v.parameters[el.dataset.cost],k=el.dataset.prop;let value=el.type==='checkbox'?el.checked:['method','rateCurrency','rateSource'].includes(k)?el.value:Number(el.value);if(el.type==='number'&&(!el.checkValidity()||el.value===''))throw Error('Проверьте значение ставки или срока.');if(k==='value'&&['payrollTax','indirectTax'].includes(el.dataset.cost)&&value>=100)throw Error('Ставка НДФЛ должна быть менее 100%.');if(k==='rateSource'&&value.length>500)throw Error('Основание ставки: не более 500 символов.');if(k==='rateCurrency'&&value&&value!==v.currency&&(!(fxOf(v)>0)||!['RUB','USD'].includes(value)||!['RUB','USD'].includes(v.currency)))throw Error('Для пересчёта ставки укажите курс к RUB и поддерживаемую пару RUB/USD.');p[k]=value;}
 else return;persist(true,el.dataset.general==='contractorName'?'both':'contractor');render();
 }catch(err){notify(err.message);render();}}
function exportModel(){if(!state.results)return;const v=version(),groups=modelRows(),rows=[['Раздел','Статья','Представление','Валюта','Контрактный курс к RUB',...MONTHS,'За год / на конец']];for(const [g,rs] of Object.entries(groups))for(const r of rs){const total=r[3]==='last'?r[1].at(-1):sum(r[1]);rows.push([g,r[0],'Исходные значения',v.currency,fxOf(v),...r[1],total]);if(v.currency!=='RUB')rows.push([g,r[0],'Рублёвый эквивалент','RUB',fxOf(v),...r[1].map(x=>rub(x,v)),rub(total,v)]);}download('model_'+contract().number.replace(/[^\p{L}\p{N}_-]/gu,'_')+'.csv','\ufeff'+rows.map(r=>r.map(x=>'"'+String(typeof x==='number'?x.toFixed(2).replace('.',','):x).replaceAll('"','""')+'"').join(';')).join('\n'),'text/csv;charset=utf-8');notify('CSV выгружен с валютой договора, контрактным курсом и отдельным рублёвым эквивалентом.');}

