 const c=contractor();$('contractorFileSettings').innerHTML=`<div class="formgrid"><div class="wide"><label for="contractorFileUrl">Файл выбранного подрядчика в SharePoint или репозитории</label><div class="actions"><input id="contractorFileUrl" type="url" style="min-width:min(620px,100%);flex:1" value="${esc(c.fileUrl||'')}" placeholder="https://…/contractor.xlsx"><button class="btn" id="loadContractorUrl">Загрузить по ссылке</button><button class="btn" id="downloadContractorHere">Скачать Excel</button></div><p class="sub">Общий config.json хранит только ссылку на этот файл. Договоры, цены, расчёты и карта источников находятся в Excel-файле выбранного подрядчика.</p>${c.loadError?`<div class="note warning">${esc(c.loadError)}</div>`:''}</div></div>`;
 $('contractorFileUrl').disabled=!editMode;$('contractorFileUrl').onchange=e=>{if(!requireEdit())return;c.fileUrl=e.target.value.trim();persist(true,'config');};$('downloadContractorHere').onclick=exportContractor;$('loadContractorUrl').onclick=loadCurrentContractorFile;
 if(!contract()){$('sourceList').innerHTML='<div class="note warning">Для подрядчика не загружен файл с договорами и моделью.</div>';return;}
 $('sourceList').innerHTML='<div class="source-grid">'+SOURCE_KEYS.map(([k,label])=>{const p=sourceProfile(k),meta=contract().sources[k],book=sourceCache.get(sourceToken(k));return `<div class="source-card"><div class="sectionhead"><h3>${label}</h3><span class="status ${book?'':'warn'}">${book?'Данные прочитаны':meta?.appliedAt?'Данные применены к версии':'Не проверен'}</span></div><div class="source-path">${esc(p.path||'Ссылка не задана')}</div><p class="sub">Лист: ${esc(p.sheet||p.sheetAliases?.join(', ')||'не выбран')}${meta?.name?' · '+esc(meta.name):''}</p><div class="actions"><button class="btn" data-source="${k}">Настройки и проверка</button></div></div>`;}).join('')+'</div>';
 persist();
