 try{$('openGlobalConfig').href=safeURL(configuredUrl()).href;$('openGlobalConfig').classList.remove('hidden');}catch(e){$('openGlobalConfig').removeAttribute('href');$('openGlobalConfig').classList.add('hidden');}
