async function loadCurrentContractorFile(){if(!requireEdit())return;const current=contractor(),url=$('contractorFileUrl').value.trim();if(!url){notify('Укажите прямую ссылку на Excel-файл подрядчика.');return;}if(pendingContractors.has(current.id)&&!confirm('Заменить несохранённые изменения подрядчика данными из файла по ссылке?'))return;try{safeURL(url);const loaded=await contractorFromUrl({id:current.id,name:current.name,fileUrl:url}),index=state.contractors.findIndex(x=>x.id===current.id),urlChanged=current.fileUrl!==url;state.contractors[index]=loaded;state.currentContract='';state.currentVersion='';pendingContractors.delete(current.id);contractorDirty=pendingContractors.size>0;dirty=contractorDirty||configDirty;normalize();persist(urlChanged,'config');render();notify('Файл подрядчика загружен по ссылке. Браузерное хранилище не использовалось.');}catch(e){notify('Не удалось загрузить файл подрядчика: '+e.message);}}
function safeURL(path){const url=new URL(path,location.href);if(!['http:','https:','file:'].includes(url.protocol))throw Error('Допустимы ссылки HTTP(S) или относительные пути к файлам.');return url;}
function openSource(k){sourceKey=k;sourceDraft=sourceProfile(k);sourceDraft.overrides=sourceDraft.overrides||{};previewCandidate=null;$('sourceTitle').textContent=SOURCE_KEYS.find(x=>x[0]===k)[1]+' · источник и соответствия';$('sourceModal').classList.add('show');renderSourceEditor();$('sourcePreview').innerHTML='';}
function renderSourceEditor(){const p=sourceDraft,book=sourceCache.get(sourceToken()),fields={...(p.fields||{})};Object.keys(p.overrides||{}).forEach(k=>fields[k]=fields[k]||[]);const bind=version().bindings[sourceKey]||{};
 $('sourceEditor').innerHTML=`<div class="formgrid"><div class="wide"><label for="sourcePath">Ссылка на документ или относительный путь</label><input id="sourcePath" value="${esc(p.path||'')}" placeholder="data/sources/document.xlsx"></div><div><label for="sourceSheet">Лист Excel</label><input id="sourceSheet" list="sheetOptions" value="${esc(p.sheet||'')}" placeholder="Выберите после чтения файла"><datalist id="sheetOptions">${(book?.sheets||[]).map(x=>`<option value="${esc(x.name)}">`).join('')}</datalist></div><div><label for="sourceHeader">Строка заголовков (0 — найти по полям)</label><input id="sourceHeader" type="number" min="0" max="1048576" value="${p.headerRow?.mode==='manual'?p.headerRow.fallback:0}"></div><div><label for="sourceStart">Первая строка данных (0 — после заголовка)</label><input id="sourceStart" type="number" min="0" value="${p.startRow||0}"></div><div><label for="sourceEnd">Последняя строка данных (0 — до конца)</label><input id="sourceEnd" type="number" min="0" value="${p.endRow||0}"></div></div><div class="actions"><button class="btn" id="readSourceUrl">Прочитать по ссылке</button><button class="btn" id="readSourceFile">Выбрать файл</button><span class="sub">Excel .xlsx, CSV, TSV</span></div><details class="group-panel" open><summary>Поля документа → колонки или ячейки</summary><div class="group-content"><p class="sub">Для колонки укажите букву (D, AA), для ячейки — адрес (D12). По заголовку можно оставить встроенные варианты или указать точное название.</p>${Object.entries(fields).map(([k,aliases])=>{const f=p.overrides[k]||{mode:'header',value:''};return `<div class="source-fields"><div><b>${esc(k)}</b>${p.requiredFields?.includes(k)?' *':''}<div class="sub">${esc(Array.isArray(aliases)?aliases.slice(0,2).join(' / '):aliases)}</div></div><select data-field-mode="${esc(k)}">${[['header','Заголовок'],['column','Колонка'],['cell','Ячейка']].map(([a,b])=>`<option value="${a}" ${f.mode===a?'selected':''}>${b}</option>`).join('')}</select><input data-field-value="${esc(k)}" value="${esc(f.value)}" aria-label="${esc(k)} — источник"></div>`;}).join('')}</div></details>
 <details class="group-panel" open><summary>Передача данных в модель</summary><div class="group-content"><p class="sub">Укажите получателя и 12 месячных ячеек либо колонки даты и значения. Проверьте результат, затем примените его к текущей версии. Одна настройка на источник; для другого показателя измените получателя и повторите.</p><div class="binding-row"><label>Показатель<select id="bindTarget">${SERIES.map(([k,l])=>`<option value="driver:${k}" ${bind.target==='driver:'+k?'selected':''}>${l}</option>`).join('')}${COST_DEFS.map(x=>`<option value="cost:${x[2]}" ${bind.target==='cost:'+x[2]?'selected':''}>Расход: ${x[0]==='direct'?'прямой':'косвенный'} · ${x[1]}</option>`).join('')}${COST_DEFS.map(x=>`<option value="payment:${x[2]}" ${bind.target==='payment:'+x[2]?'selected':''}>Выплата: ${x[0]==='direct'?'прямая':'косвенная'} · ${x[1]}</option>`).join('')}</select></label><label>Способ<select id="bindMode"><option value="cells" ${bind.mode!=='rows'?'selected':''}>12 месячных ячеек</option><option value="rows" ${bind.mode==='rows'?'selected':''}>По датам в строках</option></select></label><label>Диапазон / 12 адресов по месяцам<input id="bindCells" value="${esc(bind.cells||'')}" placeholder="B12:M12 или B12,B15,…"></label></div><div class="binding-row"><label>Колонка даты<input id="bindDate" value="${esc(bind.date||'')}" placeholder="A или @document_date"></label><label>Колонка значения<input id="bindValue" value="${esc(bind.value||'')}" placeholder="F или @amount_without_vat"></label><label>Коэффициент перевода в рубли / единицы<input id="bindScale" type="number" step="any" value="${bind.scale??1}"></label></div><div class="binding-row"><label>Отбор по колонке (необязательно)<input id="bindFilterCol" value="${esc(bind.filterCol||'')}" placeholder="C или @expense_type"></label><label>Значение отбора<input id="bindFilterValue" value="${esc(bind.filterValue||'')}"></label><label><input type="checkbox" id="bindScope" ${bind.scope!==false?'checked':''}> Отбирать текущего подрядчика и договор по настроенным полям</label></div><p class="sub">Для режима ячеек диапазон должен уже относиться к выбранному договору. В числовых рядах пустые или текстовые значения считаются ошибкой.</p><button class="btn" id="previewBinding">Предпросмотр месячных данных</button><div id="bindingPreview"></div></div></details>`;
 $('sourceEditor').querySelectorAll('input,select').forEach(x=>x.disabled=!editMode);
 $('readSourceUrl').onclick=()=>loadSourceURL();$('readSourceFile').onclick=()=>{pendingSource=sourceKey;$('sourceFile').click();};$('previewBinding').onclick=()=>previewBinding();
 $('sourceEditor').addEventListener('change',invalidatePreview,{once:true});
}
function invalidatePreview(){previewCandidate=null;$('bindingPreview').innerHTML='';}
function collectSource(){if(!editMode)return sourceDraft;const p=clone(sourceDraft);p.path=$('sourcePath').value.trim();if(p.path)safeURL(p.path);p.sheet=$('sourceSheet').value.trim();const h=Number($('sourceHeader').value);if(!Number.isInteger(h)||h<0)throw Error('Строка заголовков должна быть целым неотрицательным числом.');p.headerRow={...(p.headerRow||{}),mode:h?'manual':'auto',fallback:h||p.headerRow?.fallback||1};p.startRow=Number($('sourceStart').value)||0;p.endRow=Number($('sourceEnd').value)||0;if(!Number.isInteger(p.startRow)||!Number.isInteger(p.endRow)||p.startRow<0||p.endRow<0||(p.endRow&&p.startRow>p.endRow))throw Error('Проверьте границы строк.');p.overrides={};for(const el of $('sourceEditor').querySelectorAll('[data-field-mode]')){const k=el.dataset.fieldMode,value=[...$('sourceEditor').querySelectorAll('[data-field-value]')].find(x=>x.dataset.fieldValue===k).value.trim();if(el.value==='column'&&!/^[A-Z]{1,3}$/i.test(value))throw Error(k+': укажите букву колонки.');if(el.value==='cell'&&!/^\$?[A-Z]{1,3}\$?[1-9]\d*$/i.test(value))throw Error(k+': укажите адрес ячейки.');p.overrides[k]={mode:el.value,value};}return p;}
function collectBinding(){return {target:$('bindTarget').value,mode:$('bindMode').value,cells:$('bindCells').value.trim(),date:$('bindDate').value.trim(),value:$('bindValue').value.trim(),scale:Number($('bindScale').value),filterCol:$('bindFilterCol').value.trim(),filterValue:$('bindFilterValue').value.trim(),scope:$('bindScope').checked};}
function saveSource(){if(!requireEdit())return;try{sourceDraft=collectSource();contractor().sourceMapping.sources[sourceKey]=clone(sourceDraft);version().bindings[sourceKey]=collectBinding();persist(true);renderSources();notify('Настройка источника сохранена в файле выбранного подрядчика.');}catch(e){notify(e.message);}}
async function loadSourceURL(){try{sourceDraft=collectSource();if(!sourceDraft.path)throw Error('Укажите ссылку на документ.');$('sourcePreview').textContent='Чтение документа…';const u=safeURL(sourceDraft.path),r=await fetch(u,{cache:'no-store',credentials:u.origin===location.origin?'same-origin':'omit'});if(!r.ok)throw Error('HTTP '+r.status);await acceptSource(await r.arrayBuffer(),u.pathname.split('/').at(-1));}catch(e){$('sourcePreview').textContent='Не удалось прочитать источник: '+e.message+'. Можно выбрать файл вручную.';}}
async function acceptSource(buffer,name){const book=await readWorkbook(buffer,name);sourceCache.set(sourceToken(),book);if(!sourceDraft.sheet){const found=book.sheets.find(s=>(sourceDraft.sheetAliases||[]).some(a=>norm(a)===norm(s.name)));sourceDraft.sheet=found?.name||(book.sheets.length===1?book.sheets[0].name:'');}book.fileName=name;renderSourceEditor();$('sourcePreview').textContent='Прочитан файл '+name+'. Листы: '+book.sheets.map(x=>x.name).join(', ')+'. Проверьте лист и соответствия.';renderSources();}
function norm(x){return String(x??'').toLowerCase().replace(/[\s\p{P}]/gu,'');}
function colIndex(s){let n=0;for(const c of s.toUpperCase())n=n*26+c.charCodeAt(0)-64;return n-1;}
function address(s){const m=/^\$?([A-Z]{1,3})\$?([1-9]\d*)$/i.exec(String(s));if(!m)throw Error('Неверный адрес ячейки: '+s);const col=colIndex(m[1]),row=Number(m[2])-1;if(col>16383||row>1048575)throw Error('Адрес вне листа Excel.');return {col,row};}
function sheetFor(p){const book=sourceCache.get(sourceToken());if(!book)throw Error('Сначала прочитайте документ по ссылке или выберите файл.');const s=book.sheets.find(x=>x.name===p.sheet);if(!s)throw Error('Выберите точный лист из документа.');return s;}
function resolveFields(p,s){const overrides=p.overrides||{},required=p.requiredFields||[],fields=p.fields||{};let hr=(p.headerRow?.fallback||1)-1;
 if(p.headerRow?.mode!=='manual'){let best=-1,bestRow=hr;for(let row=0;row<Math.min(p.headerRow?.searchRows||50,s.maxRow+1);row++){let score=0;for(const [k,aliases] of Object.entries(fields)){const f=overrides[k];if(f&&f.mode!=='header')continue;const names=f?.value?[f.value]:aliases||[];if(s.rows[row]?.some(v=>names.some(a=>norm(a)===norm(v))))score++;}if(score>best){best=score;bestRow=row;}}hr=bestRow;}
 const resolved={},issues=[];for(const k of new Set([...Object.keys(fields),...Object.keys(overrides)])){const f=overrides[k]||{mode:'header',value:''};if(f.mode==='cell'){resolved[k]={cell:address(f.value)};continue;}if(f.mode==='column'){if(!/^[A-Z]{1,3}$/i.test(f.value))throw Error('Неверная колонка '+k);resolved[k]={col:colIndex(f.value)};continue;}const aliases=f.value?[f.value]:fields[k]||[],matches=[];(s.rows[hr]||[]).forEach((value,col)=>{if(aliases.some(a=>norm(a)===norm(value)))matches.push(col);});if(matches.length===1)resolved[k]={col:matches[0]};else if(required.includes(k))issues.push(k+': '+(matches.length?'несколько одинаковых заголовков':'не найдено'));}
 return {resolved,issues,headerRow:hr,start:Math.max(p.startRow?p.startRow-1:hr+1,0),end:p.endRow?Math.min(p.endRow-1,s.maxRow):s.maxRow};
}
function fieldValue(s,ref,row){return ref?.cell?s.rows[ref.cell.row]?.[ref.cell.col]:s.rows[row]?.[ref?.col];}
function columnName(n){let out='';for(n++;n>0;n=Math.floor((n-1)/26))out=String.fromCharCode(65+(n-1)%26)+out;return out;}
function previewFields(){try{sourceDraft=collectSource();const s=sheetFor(sourceDraft),r=resolveFields(sourceDraft,s);$('sourcePreview').innerHTML=`<div class="note ${r.issues.length?'warning':''}">${r.issues.length?esc(r.issues.join('; ')):'Обязательные поля найдены. Проверьте образцы значений.'} Строка заголовков: ${r.headerRow+1}.</div><div class="tablewrap space"><table class="mapping-preview"><thead><tr><th>Поле</th><th>Адрес</th><th>Образец</th></tr></thead><tbody>${Object.entries(r.resolved).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v.cell?columnName(v.cell.col)+(v.cell.row+1):columnName(v.col)}</td><td>${esc([0,1,2].map(i=>fieldValue(s,v,r.start+i)??'∅').join(' · '))}</td></tr>`).join('')}</tbody></table></div>`;}catch(e){$('sourcePreview').textContent=e.message;}}
function numeric(value,cell){if(typeof value==='number'&&Number.isFinite(value))return value;if(typeof value==='string'){const s=value.trim().replace(/[\s\u00a0]/g,'').replace(',','.');if(s&&/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(s)&&Number.isFinite(Number(s)))return Number(s);}throw Error('В '+cell+' ожидается число, получено: '+String(value??'пусто'));}
