function downloadBlob(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportContractor(target){const c=target?.contracts?target:contractor();if(!c)return;const date=new Date().toISOString().slice(0,10),name=(c.name||c.id).replace(/[^\p{L}\p{N}._-]+/gu,'_')+'_model_'+date+'.xlsx';downloadBlob(name,contractorWorkbookV2(c));pendingContractors.delete(c.id);contractorDirty=pendingContractors.size>0;dirty=configDirty||contractorDirty;persist();notify('Версия модели подрядчика сформирована с валютой и контрактным курсом на дату '+date+'. Сохраните её в папке подрядчика и укажите прямую ссылку в общей конфигурации.');}

const configUrlWrap=document.createElement('div');configUrlWrap.className='wide';configUrlWrap.innerHTML='<h3>Общий config.json</h3><p class="sub">Административные настройки, перечень подрядчиков и пути к их файлам. Данные отдельных подрядчиков в общий конфиг не входят.</p><label for="configUrlInput">Ссылка на config.json в репозитории или на портале</label><div class="actions"><input id="configUrlInput" type="url" style="min-width:min(620px,100%);flex:1" placeholder="https://…/config.json"><button class="btn" id="applyConfigUrl" type="button">Применить ссылку</button></div><p class="sub">После обновления страницы общие настройки загружаются только по этой ссылке. Рабочие изменения в памяти браузера не сохраняются.</p><div class="actions"><a class="btn" id="openGlobalConfig" target="_blank" rel="noopener noreferrer">Открыть config.json</a><button class="btn" id="reloadPortal" type="button">Прочитать конфиг</button><button class="btn primary" id="adminExportConfig" type="button">Скачать config.json</button><span id="saveStatus" class="sub"></span></div>';$('globalConfigSettings').append(configUrlWrap);$('configUrlInput').value=configuredUrl();$('adminExportConfig').onclick=exportConfig;
$('applyConfigUrl').onclick=()=>{if(!requireEdit())return;const raw=$('configUrlInput').value.trim();if(!raw){notify('Укажите ссылку на config.json.');return;}let resolved;try{resolved=new URL(raw,location.href);if(!['http:','https:'].includes(resolved.protocol))throw Error();}catch(e){notify('Укажите корректную HTTP(S)-ссылку или относительный путь.');return;}const url=new URL(location.href);if(resolved.href===new URL('config/config.json',location.href).href)url.searchParams.delete('config');else url.searchParams.set('config',resolved.href);history.replaceState(null,'',url);notify('Ссылка применена. Загружаю конфигурацию заново.');location.reload();};
$('editMode').onchange=e=>{const was=editMode;editMode=e.target.checked;if(editMode)state.displayCurrency='contract';document.body.classList.toggle('edit-mode',editMode);if(!editMode&&activeTab==='administration'){activeTab='summary';document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab==='summary'));}render();if($('sourceModal').classList.contains('show'))renderSourceEditor();if(was&&!editMode&&dirty){for(const id of [...pendingContractors])exportContractor(state.contractors.find(c=>c.id===id));if(configDirty)exportConfig();}};
